      "required": ["actors", "sources", "searchQueries"],
      "additionalProperties": false,
      "properties": {
        "actors": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["name", "type", "relevance", "score"],
            "additionalProperties": false,
            "properties": {
              "name": { "type": "string" },
              "type": {
                "type": "string",
                "enum": ["organization", "person", "regulator", "competitor", "ngo", "media", "other"]
              },
              "relevance": { "type": "string" },
              "score": { "type": "integer" }
            }
          }
        },
        "sources": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["name", "url", "type", "relevance", "score"],
            "additionalProperties": false,
            "properties": {
              "name": { "type": "string" },
              "url": { "type": "string" },
              "type": {
                "type": "string",
                "enum": ["website", "linkedin", "twitter", "rss", "newsletter", "database", "regulatory", "other"]
              },
              "relevance": { "type": "string" },
              "score": { "type": "integer" }
            }
          }
        },
        "searchQueries": {
          "type": "array",
          "items": { "type": "string" }
        }
      }
    },
    "deepSearchReadiness": {
      "type": "object",
      "required": ["ready", "reason", "suggestedSearchQueries"],
      "additionalProperties": false,
      "properties": {
        "ready": { "type": "boolean" },
        "reason": {
          "type": "object",
          "required": ["en", "fr"],
          "additionalProperties": false,
          "properties": {
            "en": { "type": "string" },
            "fr": { "type": "string" }
          }
        },
        "suggestedSearchQueries": {
          "type": "array",
          "items": { "type": "string" }
        }
      }
    }
  }
}

