parameters.jsCode:
const output = $input.first().json.output;

let parsed;
try {
  // Handle if output is already object or string
  parsed = typeof output === 'string' ? JSON.parse(output) : output;
} catch (e) {
  // Try to extract JSON from markdown code blocks
  const match = output.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (match) {
    parsed = JSON.parse(match[1]);
  } else {
    throw new Error('Failed to parse JSON: ' + e.message);
  }
}

// Convert "none" to null if needed
if (parsed.primarySubtype === 'none') {
  parsed.primarySubtype = null;
}


const lang = $('Code_Initialize_WatchFileData').last().json.userLanguage || 'en';

const t = (obj) => obj?.[lang] || obj?.en || '';

const header = lang === 'fr'
  ? `Le dossier de veille a été identifié comme "${parsed.primaryType}"`
  : `WatchFile has been identified as "${parsed.primaryType}"`;

const subtype = parsed.primarySubtype?.length > 0 
  ? ` (${parsed.primarySubtype})` 
  : '';

const primarySection = `## ${parsed.primaryType}\n\n${t(parsed.justification)}`;

const secondarySections = parsed.secondaryTypes
  .map(item => `## ${item.type}\n\n${t(item.justification)}`)
  .join('\n\n');

const topics = parsed.topics
  .map(item => `- ${item.label} (${item.keywords.join(', ')})`)
  .join('\n');

const keywords = parsed.analysis.detectedKeywords.join('\n- ');
const entities = parsed.analysis.detectedEntities.join('\n- ');

const actors = parsed.suggestions.actors
  .map(a => `${a.name} (${a.type}) - ${a.relevance}`)
  .join('\n- ');

const sources = parsed.suggestions.sources
  .map(s => `${s.name} (${s.type}) - ${s.relevance} ${s.url}`)
  .join('\n- ');

const sectionLabels = lang === 'fr' ? {
  topics: '## Thèmes',
  keywords: '## Mots-clés détectés',
  entities: '## Entités détectées',
  objective: '## Objectif utilisateur',
  scope: '## Périmètre géographique',
  actors: '## Suggestions d\'acteurs',
  sources: '## Suggestions de sources',
  notSpecified: 'Non spécifié'
} : {
  topics: '## Topics',
  keywords: '## Detected keywords',
  entities: '## Detected entities',
  objective: '## User objective',
  scope: '## Geographic scope',
  actors: '## Actor suggestions',
  sources: '## Source suggestions',
  notSpecified: 'Not specified'
};

const message = `${header}${subtype}.

${primarySection}

${secondarySections}

${sectionLabels.topics}
${topics}

${sectionLabels.keywords}
- ${keywords}

${sectionLabels.entities}
- ${entities}

${sectionLabels.objective}
${parsed.analysis.userObjective}

${sectionLabels.scope}
${parsed.analysis.geographicScope || sectionLabels.notSpecified}

${sectionLabels.actors}
- ${actors}

${sectionLabels.sources}
- ${sources}`;

parsed.message = message;

return {
  json: parsed
};
